const cx=W()/2, cy=H()/2;
const bokeh=[];
for(let i=0;i<14;i++){
  const ang=Math.random()*Math.PI*2;
  const dist= Math.min(W(),H())*(0.35+Math.random()*0.55);
  bokeh.push({
    x: cx+Math.cos(ang)*dist,
    y: cy+Math.sin(ang)*dist*0.8,
    r: 28+Math.random()*60,
    a: 0.04+Math.random()*0.07,
    phase: Math.random()*Math.PI*2,
    speed: 0.0004+Math.random()*0.0005,
    c: PALETTE[i%PALETTE.length]
  });
}

const drops=[];
function spawnDrop(){
  const side = Math.random()<0.5?-1:1;
  const x = cx + side*(Math.min(W(),H())*0.32 + Math.random()*W()*0.18);
  drops.push({
    x, y:-30-Math.random()*80,
    vx:(Math.random()-0.5)*0.1,
    vy:0.35+Math.random()*0.45,
    r:1.6+Math.random()*3.2,
    trail:[],
    c: PALETTE[Math.floor(Math.random()*PALETTE.length)],
    sway: Math.random()*Math.PI*2
  });
}
for(let i=0;i<30;i++){ spawnDrop(); drops[i].y = Math.random()*H(); }

function hexA(hex, a){
  const h = hex.replace('#','');
  const r = parseInt(h.substring(0,2),16);
  const g = parseInt(h.substring(2,4),16);
  const b = parseInt(h.substring(4,6),16);
  return 'rgba('+r+','+g+','+b+','+Math.max(0,Math.min(1,a))+')';
}

let t0=null;
function frame(ts){
  if(!t0) t0=ts;
  const time=(ts-t0)/1000;
  ctx.clearRect(0,0,W(),H());

  for(const b of bokeh){
    const pulse = 0.6+0.4*Math.sin(time*b.speed*60 + b.phase);
    const grad = ctx.createRadialGradient(b.x,b.y,0,b.x,b.y,b.r);
    grad.addColorStop(0, hexA(b.c, b.a*pulse));
    grad.addColorStop(1, hexA(b.c, 0));
    ctx.fillStyle=grad;
    ctx.beginPath();
    ctx.arc(b.x,b.y,b.r,0,Math.PI*2);
    ctx.fill();
  }

  for(const d of drops){
    d.sway += 0.01;
    d.x += d.vx + Math.sin(d.sway)*0.12;
    d.y += d.vy;
    d.trail.push({x:d.x,y:d.y});
    if(d.trail.length>18) d.trail.shift();

    const distC = Math.hypot(d.x-cx, d.y-cy);
    const safe = Math.min(W(),H())*0.3;
    const fade = distC<safe ? Math.max(0, distC/safe) : 1;

    ctx.beginPath();
    for(let i=0;i<d.trail.length;i++){
      const p=d.trail[i];
      const alpha=(i/d.trail.length)*0.5*fade;
      ctx.strokeStyle = hexA(d.c, alpha);
      ctx.lineWidth = d.r*(i/d.trail.length);
      if(i===0) ctx.moveTo(p.x,p.y); else ctx.lineTo(p.x,p.y);
    }
    ctx.stroke();

    ctx.save();
    ctx.shadowBlur = 12;
    ctx.shadowColor = d.c;
    ctx.fillStyle = hexA(d.c, 0.85*fade);
    ctx.beginPath();
    ctx.arc(d.x,d.y,d.r,0,Math.PI*2);
    ctx.fill();
    ctx.restore();

    if(d.y > H()+40){
      d.y = -30-Math.random()*80;
      const side = Math.random()<0.5?-1:1;
      d.x = cx + side*(Math.min(W(),H())*0.32 + Math.random()*W()*0.18);
      d.trail = [];
    }
  }

  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);
